# frozen_string_literal: true

module Worklog
  # One line of a Claude Code transcript.
  class Entry
    # User messages starting with these are generated by the harness, not typed by the user.
    NON_PROMPT_PREFIXES = [
      "<local-command-",
      "<task-notification",
      "<command-message",
      "<system-reminder",
      "This session is being continued from a previous",
    ].freeze

    # Returns nil for lines that are not valid JSON.
    def self.parse(line)
      new(PyCompat.parse_json(line))
    rescue JSON::ParserError
      nil
    end

    def initialize(attributes)
      @attributes = attributes
    end

    def type
      @attributes["type"]
    end

    def ai_title
      @attributes["aiTitle"] if type == "ai-title" && PyCompat.truthy?(@attributes["aiTitle"])
    end

    def sidechain?
      PyCompat.truthy?(@attributes["isSidechain"])
    end

    def meta?
      PyCompat.truthy?(@attributes["isMeta"])
    end

    def cwd
      @attributes["cwd"] if PyCompat.truthy?(@attributes["cwd"])
    end

    def git_branch
      branch = @attributes["gitBranch"]
      branch if PyCompat.truthy?(branch) && branch != "HEAD"
    end

    # User or assistant message with a timestamp; counts as activity in the timeline.
    def activity?
      PyCompat.truthy?(@attributes["timestamp"]) && %w[user assistant].include?(type)
    end

    def time
      PyCompat.parse_time(@attributes["timestamp"])
    end

    # The user-typed text of this entry, or nil if it is not a prompt.
    def prompt_text
      return @prompt_text if defined?(@prompt_text)

      @prompt_text = extract_prompt_text
    end

    def prompt?
      !prompt_text.nil?
    end

    private

    def extract_prompt_text
      return nil if type != "user" || sidechain? || meta?

      content = message_content
      return nil if !content.is_a?(String) || PyCompat.strip(content).empty?

      text = PyCompat.strip(content)
      return nil if text.start_with?(*NON_PROMPT_PREFIXES)
      return slash_command(text) if text.start_with?("<command-name>")

      text
    end

    def message_content
      message = @attributes["message"]
      content = (PyCompat.truthy?(message) ? message : {})["content"]
      return content unless content.is_a?(Array)

      texts = content.select { |c| c.is_a?(Hash) && c["type"] == "text" }.map { |c| c.fetch("text", "") }
      texts.empty? ? nil : texts.join("\n")
    end

    # Keep only "/name args" from the harness markup of a slash command.
    def slash_command(text)
      name = text.partition("<command-name>")[2].partition("</command-name>")[0]
      args = ""
      args = text.partition("<command-args>")[2].partition("</command-args>")[0] if text.include?("<command-args>")
      PyCompat.strip("#{name} #{args}")
    end
  end
end
